def log(s): print(f"[{datetime.now(TAIPEI).strftime('%H:%M:%S')}] {s}", flush=True)
def norm(s): return re.sub(r'[\s\u3000_\-（）()\[\]／/：:、,.%]+','',str(s or '').strip().lower())
def find_col(cols, aliases):
    lookup={norm(c):c for c in cols}
    for a in aliases:
        if norm(a) in lookup: return lookup[norm(a)]
    return None
def parse_market(x):
    s=str(x or '').strip().upper()
    if s in {'TWSE','上市','集中市場','上市市場'}: return 'TWSE'
    if s in {'TPEX','TPEX','TPEx','上櫃','櫃買','上櫃市場'}: return 'TPEX'
    return ''
def parse_date(x):
    s=str(x or '').strip().replace('/','-')
    if not s: return ''
    # ROC year formats: 115-11-13 / 1151106
    m=re.fullmatch(r'(\d{2,3})-?(\d{2})-?(\d{2})',s)
    if m and int(m.group(1)) < 1911:
        return f"{int(m.group(1))+1911:04d}-{int(m.group(2)):02d}-{int(m.group(3)):02d}"
    try: return datetime.fromisoformat(s[:10]).date().isoformat()
    except Exception: return ''
# Bridge missing-value contract: empty fields and exchange placeholders are one semantic NA.
# Keep numeric zero as 0.0; do not use `x or ''`, which would erase numeric zero.
_MISSING_NUM_TOKENS = {
    '', '-', '--', '---', '----', '-----', 'nan', 'nat', 'none', 'null',
    'na', 'n/a', 'n.a.', 'nil', '未提供', '無資料', '無報價',
}
_DASH_ONLY_RE = re.compile(r'^[\s\-‐‑‒–—―−－﹣]+$')

def num(x):
    '''Normalize official OHLCV values. Blank / ---- / dash-only placeholders -> None.'''
    if x is None:
        return None
    s = str(x).strip().replace(',', '').replace('＋', '+').replace('－', '-')
    if s.casefold() in _MISSING_NUM_TOKENS or _DASH_ONLY_RE.fullmatch(s):
        return None
    try:
        value = float(s)
        return value if math.isfinite(value) else None
    except (TypeError, ValueError, OverflowError):
        # Unparseable textual placeholders are missing, not numerical disagreements.
        return None


def norm_full_pool_code(value):
    '''Same full-code identity as the v2.67 exact pool reader; preserve suffixes.'''
    if value is None:
        return ''
    code = re.sub(r'\s+', '', str(value).strip().upper().replace('\ufeff', ''))
    code = re.sub(r'\.(?:TWO|TW)$', '', code)
    if not code or code in {'NAN', 'NONE', 'NULL', '-', '--'}:
        return ''
    if re.fullmatch(r'\d+\.0+', code):
        code = code.split('.', 1)[0]
    if code.isdigit():
        return code.zfill(4) if len(code) <= 4 else code
    return code


def norm_legacy_pool_code(value):
    '''v4.16-v4.24 legacy projection; used only to explain the old-code scope.'''
    if value is None:
        return ''
    code = str(value).strip().upper().replace('.TWO', '').replace('.TW', '')
    if re.fullmatch(r'\d+\.0+', code):
        code = code.split('.', 1)[0]
    if re.fullmatch(r'\d+', code):
        return code.zfill(4) if len(code) <= 4 else code
    m = re.search(r'\d+', code)
    if m:
        digits = m.group(0)
        return digits.zfill(4) if len(digits) <= 4 else digits
    return code


def load_exact_pool_codes():
    '''Read only the v2.67 exact-code pool; never broaden by legacy prefix.'''
    pool_path = ANALYSIS / '台股股票池.csv'
    if not pool_path.is_file():
        raise FileNotFoundError(f'找不到 v2.67 股票池：{pool_path}')
    last = None
    for enc in ('utf-8-sig', 'utf-8', 'cp950', 'big5'):
        try:
            f = pool_path.open('r', encoding=enc, newline='')
            f.read(4096); f.seek(0)
            break
        except Exception as exc:
            last = exc
    else:
        raise RuntimeError(f'無法讀取股票池 {pool_path}: {last}')
    try:
        reader = csv.DictReader(f)
        headers = reader.fieldnames or []
        aliases = ('股票代號', '股票代碼', '證券代號', '代號', 'code', 'symbol', 'ticker')
        exact_col = next((c for c in aliases if c in headers), None)
        ticker_col = next((c for c in headers if 'yahoo' in c.lower() or 'ticker' in c.lower()), None)
        if not exact_col:
            raise RuntimeError(f'股票池無法依 v2.67 規則找到完整代號欄位：{headers}')
        codes = set()
        for row in reader:
            code = norm_full_pool_code(row.get(exact_col, ''))
            if not code and ticker_col:
                code = norm_full_pool_code(row.get(ticker_col, ''))
            if code:
                codes.add(code)
        if len(codes) != 1985:
            raise RuntimeError(f'股票池完整代號集合數改變：{len(codes)}，歷史稽核基準為 1,985；停止避免範圍誤判。')
        return codes, {'path': str(pool_path), 'encoding': enc, 'code_column': exact_col,
                       'exact_code_count': len(codes), 'legacy_projection_used_for_inclusion': False}
    finally:
        f.close()


def audit_target_no_price_keys(key_path):
    '''Verify exact target-date membership of 1538/2321 in v2.70's 4,673-key list.'''
    targets = {('2026-10-28', 'TWSE', '1538'), ('2026-10-28', 'TWSE', '2321')}
    codes = {'1538', '2321'}
    exact = {k: [] for k in targets}
    other_dates = {c: [] for c in codes}
    row_count = 0
    unique = set()
    with Path(key_path).open('r', encoding='utf-8-sig', newline='') as f:
        reader = csv.DictReader(f)
        required = {'日期', '市場', '股票代號', '原因'}
        if not required.issubset(set(reader.fieldnames or [])):
            raise RuntimeError(f'4,673筆異常鍵清單欄位不足：{reader.fieldnames}')
        for r in reader:
            row_count += 1
            d = parse_date(r.get('日期'))
            m = parse_market(r.get('市場'))
            c = norm_full_pool_code(r.get('股票代號'))
            key = (d, m, c)
            unique.add(key)
            if key in exact:
                reason = str(r.get('原因', '')).strip()
                exact[key].append({'日期': d, '市場': m, '股票代號': c, '原因': reason,
                                   'reason_matches_v270_no_price_class': reason == EXPECTED_NO_PRICE_REASON})
            if m == 'TWSE' and c in codes:
                other_dates[c].append({'日期': d, '原因': str(r.get('原因', '')).strip()})
    if row_count != EXPECTED_NO_PRICE or len(unique) != EXPECTED_NO_PRICE:
        raise RuntimeError(f'異常鍵清單筆數／唯一鍵數不符：{row_count}/{len(unique)}，預期 4,673/4,673')
    items = []
    for key in sorted(targets):
        c = key[2]
        items.append({
            'target_key': {'date': key[0], 'market': key[1], 'code': c},
            'present_in_4673_exact_target': bool(exact[key]),
            'exact_target_rows': exact[key],
            'exact_target_reason_valid': bool(exact[key]) and all(x['reason_matches_v270_no_price_class'] for x in exact[key]),
            'same_market_same_code_all_key_rows': other_dates[c],
            'same_market_same_code_total_occurrence_count': len(other_dates[c]),
        })
    return {
        'key_file': str(key_path), 'rows': row_count, 'unique_natural_keys': len(unique),
        'target_checks': items,
        'both_exact_target_keys_present': all(bool(exact[k]) for k in targets),
        'both_exact_target_keys_match_v270_no_price_reason': all(
            bool(exact[k]) and all(x['reason_matches_v270_no_price_class'] for x in exact[k]) for k in targets),
        'interpretation': 'PRESENT_AND_REASON_VALID' if all(
            bool(exact[k]) and all(x['reason_matches_v270_no_price_class'] for x in exact[k]) for k in targets
        ) else 'MISSING_OR_REASON_MISMATCH',
    }


def run_bridge_unit_tests():
    '''Deterministic tests for the bridge's missing-value semantics and code scope.'''
    missing = ['', ' ', '-', '--', '----', '—', '–', '－', 'nan', 'None', 'N/A']
    assert all(num(x) is None for x in missing), f'missing placeholder normalization failed: {missing}'
    assert num(0) == 0.0 and num('0') == 0.0 and num('12.5') == 12.5
    assert norm_full_pool_code('00679B') == '00679B'
    assert norm_legacy_pool_code('00679B') == '00679'
    assert norm_legacy_pool_code('5871-KY') == '5871'
    assert num('----') == num('') is None
    # An exact-pool key may be absent from the price master only when the
    # exact natural key is in the audited 4,673-key no-price list and its
    # independent A/v4.17 record has all OHLC missing and positive volume.
    reason = EXPECTED_NO_PRICE_REASON
    assert classify_authorized_no_price((None, None, None, None, 242), reason)
    assert not classify_authorized_no_price((None, 10, None, None, 242), reason)
    assert not classify_authorized_no_price((None, None, None, None, 0), reason)
    assert not classify_authorized_no_price((None, None, None, None, 242), 'OTHER')
    # Regression test for v5.4 NameError: validate_and_merge must have a local
    # stat object, and the helper must reject a state/file size disagreement.
    import tempfile
    global DELTA_PATH
    old_delta_path = DELTA_PATH
    try:
        with tempfile.TemporaryDirectory(prefix='sso_v55_delta_stat_') as td:
            test_delta = Path(td) / 'delta.csv.gz'
            test_delta.write_bytes(b'1234567')
            DELTA_PATH = test_delta
            test_stat = snapshot_delta_stat({'delta_size_bytes': 7})
            assert test_stat.st_size == 7
            try:
                snapshot_delta_stat({'delta_size_bytes': 8})
            except RuntimeError:
                pass
            else:
                raise AssertionError('delta size mismatch should block')
    finally:
        DELTA_PATH = old_delta_path
    return {'missing_placeholders_test': 'PASS', 'zero_preservation_test': 'PASS',
            'full_code_identity_test': 'PASS', 'legacy_projection_test': 'PASS',
            'audited_no_price_exception_test': 'PASS',
            'delta_stat_nameerror_regression_test': 'PASS',
            'delta_state_size_guard_test': 'PASS'}
def sha256(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as f:
        for b in iter(lambda:f.read(16*1024*1024),b''): h.update(b)
    return h.hexdigest()
def read_json(path): return json.loads(Path(path).read_text(encoding='utf-8-sig'))
def write_json(path, obj):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, ensure_ascii=False, indent=2, default=str), encoding='utf-8-sig')
