def _walk_sso_project_files():
    """唯讀掃描 SSO 專案；略過不相關的大型目錄並保留搜尋錯誤。"""
    roots = [PROJECT]
    try:
        if ANALYSIS.resolve() != PROJECT.resolve() and PROJECT.resolve() not in ANALYSIS.resolve().parents:
            roots.insert(0, ANALYSIS)
    except Exception:
        roots.insert(0, ANALYSIS)
    seen_roots = set()
    files = []
    folders = []
    errors = []
    skip = {'.git', '__pycache__', '.ipynb_checkpoints', 'node_modules', '巡田最速適', '.Trash', '垃圾桶'}
    for root in roots:
        try:
            root = root.resolve()
        except Exception:
            continue
        if root in seen_roots or not root.is_dir():
            continue
        seen_roots.add(root)
        def _onerror(exc):
            errors.append(f'{getattr(exc, "filename", root)}: {type(exc).__name__}: {exc}')
        for current, dirs, names in os.walk(root, topdown=True, onerror=_onerror, followlinks=False):
            dirs[:] = [d for d in dirs if d not in skip and not d.startswith('.')]
            cur = Path(current)
            for d in list(dirs):
                dp = cur / d
                if d.startswith('SFAS_官方市場行情資料底稿_v2.8_'):
                    folders.append(dp)
            for name in names:
                if (name in {'官方行情總表.csv', '官方資料未解決異常鍵值.csv', '執行摘要.json'}
                    or name.startswith('SFAS_v2.8_十年官方行情修正整合_') and name.lower().endswith('.zip')):
                    files.append(cur / name)
            if len(files) % 1000 == 0 and files:
                pass
    # de-duplicate while preserving deterministic order
    files = sorted({x.resolve() for x in files if x.exists()}, key=lambda x: str(x))
    folders = sorted({x.resolve() for x in folders if x.exists()}, key=lambda x: str(x))
    return files, folders, errors, [str(x) for x in seen_roots]


def _validate_v267_summary(summary_path):
    data = read_json(summary_path)
    version = str(data.get('版本', ''))
    rows = int(data.get('修正後行情列數', data.get('輸出行情列數', -1)) or -1)
    bad_keys = int(data.get('未解決資料異常鍵值數', data.get('未解決異常鍵值數', -1)) or -1)
    end_date = parse_date(data.get('最晚行情日期') or (data.get('日期範圍') or {}).get('迄日'))
    if 'v2.67' not in version:
        raise RuntimeError(f'摘要版本不是 v2.67：{version!r}')
    if rows != 4447168:
        raise RuntimeError(f'摘要修正後行情列數不符：{rows}，預期 4,447,168')
    if bad_keys != EXPECTED_NO_PRICE:
        raise RuntimeError(f'摘要未解決異常鍵值數不符：{bad_keys}，預期 {EXPECTED_NO_PRICE}')
    if end_date != '2026-10-28':
        raise RuntimeError(f'摘要最晚行情日期不符：{end_date!r}，預期 2026-10-28')
    return data


def _validate_v270_key_file(key_path):
    count = 0
    reasons = Counter()
    unique = set()
    with Path(key_path).open('r', encoding='utf-8-sig', newline='') as f:
        reader = csv.DictReader(f)
        required = {'日期', '市場', '股票代號', '原因'}
        if not required.issubset(set(reader.fieldnames or [])):
            raise RuntimeError(f'未解決鍵值欄位不足：{reader.fieldnames}')
        for r in reader:
            count += 1
            reasons[str(r.get('原因', '')).strip()] += 1
            unique.add((parse_date(r.get('日期')), parse_market(r.get('市場')), str(r.get('股票代號', '')).strip()))
    if count != EXPECTED_NO_PRICE or len(unique) != EXPECTED_NO_PRICE:
        raise RuntimeError(f'未解決鍵值數／唯一鍵數錯誤：{count}/{len(unique)}，預期 {EXPECTED_NO_PRICE}')
    expected_reason = '官方重查仍有無效OHLCV:OHLCV缺值/非數值:開盤,最高,最低,收盤'
    if set(reasons) != {expected_reason}:
        raise RuntimeError(f'v2.70 官方無價格原因不一致：{dict(reasons)}')
    return {'key_rows': count, 'unique_keys': len(unique), 'reason_counts': dict(reasons)}


def _extract_v267_bundle(zip_path, work_dir):
    """只從 v2.67 輸出 ZIP 抽取必要三檔至 /content，不解壓其他大型內容。"""
    import zipfile
    from pathlib import PurePosixPath
    required = ['官方行情總表.csv', '官方資料未解決異常鍵值.csv', '執行摘要.json']
    target = Path(work_dir) / 'v267_source_bundle' / Path(zip_path).stem
    target.mkdir(parents=True, exist_ok=False)
    with zipfile.ZipFile(zip_path, 'r') as zf:
        members = zf.namelist()
        chosen = {}
        for basename in required:
            matches = [m for m in members if PurePosixPath(m).name == basename]
            if len(matches) != 1:
                raise RuntimeError(f'v2.67 ZIP 成員 {basename} 命中數不是1：{len(matches)}')
            chosen[basename] = matches[0]
        for basename, member in chosen.items():
            info = zf.getinfo(member)
            if info.file_size <= 0:
                raise RuntimeError(f'v2.67 ZIP 必要成員為空：{member}')
            out = target / basename
            with zf.open(member, 'r') as src, out.open('wb') as dst:
                shutil.copyfileobj(src, dst, length=8 * 1024 * 1024)
    return target, target / required[0], target / required[1], target / required[2], chosen


