def _file_sha256(path: Path) -> str:
    h = hashlib.sha256()
    with Path(path).open('rb') as f:
        for block in iter(lambda: f.read(8 * 1024 * 1024), b''):
            h.update(block)
    return h.hexdigest()


def _latest_v1516_run(root: Path) -> tuple[Path, dict]:
    """Select the newest v1.5.16 run and require its same-day gate contract."""
    candidates = []
    for folder in root.glob('v1.5.16_同日閘門與官方日曆核驗_*'):
        report_path = folder / V1516_REPORT_NAME
        calendar_path = folder / V1516_CALENDAR_NAME
        task_path = folder / V1516_TASKS_NAME
        if folder.is_dir() and report_path.is_file() and calendar_path.is_file() and task_path.is_file():
            candidates.append((folder.stat().st_mtime_ns, folder, report_path))
    if not candidates:
        raise FileNotFoundError(
            '找不到 v1.5.16 最新成功輸出；請先執行 '
            'SSO_Market_Data_Continuation_TWSE_TPEX_v1.5.16.py。'
        )
    _, folder, report_path = max(candidates, key=lambda x: (x[0], x[1].name))
    report = read_json(report_path)
    if report.get('version') != 'SSO_Market_Data_Continuation_TWSE_TPEX_v1.5.16':
        raise RuntimeError(f'最新 v1.5.16 報告版本不符：{report.get("version")}')
    if report.get('status') != 'SUCCESS' or report.get('downstream_ready') is not True:
        raise RuntimeError('最新 v1.5.16 未達 SUCCESS/downstream_ready=True；停止推薦流程。')
    tests = report.get('function_tests') or []
    if len(tests) != 8 or any(str(x.get('status', '')).upper() != 'PASS' for x in tests):
        raise RuntimeError(f'v1.5.16 函數測試沒有全部 8/8 PASS；實際={tests}')
    window = report.get('check_window') or {}
    if int(window.get('calendar_days', 0)) != 30:
        raise RuntimeError(f'行情來源檢查窗口不是30日：{window}')
    execution_day = parse_date(window.get('execution_date_taipei'))
    end_day = parse_date(window.get('end'))
    same_day_included = window.get('same_day_included')
    if execution_day is None or end_day is None or not isinstance(same_day_included, bool):
        raise RuntimeError(f'v1.5.16同日閘門欄位缺漏或無效：{window}')
    expected_end = execution_day if same_day_included else execution_day - timedelta(days=1)
    if end_day != expected_end:
        raise RuntimeError(
            f'v1.5.16日期截止日與17:00同日閘門不一致：end={end_day}；'
            f'execution={execution_day}；same_day_included={same_day_included}'
        )
    if len(report.get('unresolved_market_days') or []) != 0:
        raise RuntimeError('v1.5.16仍有未解決市場日；停止推薦流程。')
    if len(report.get('partial_day_suspects') or []) != 0:
        raise RuntimeError('v1.5.16仍有疑似不完整市場日；停止推薦流程。')
    if not (report.get('integration') or {}).get('standardized_increment_saved_under_v1_5_16'):
        raise RuntimeError('v1.5.16報告未確認標準化增量已寫入版本資料夾。')
    return folder, report


def _read_v1516_backfill_evidence(run_folder: Path, report: dict) -> tuple[dict, dict]:
    """Validate task CSV against the actual standardized increment before trusting same-day rows."""
    task_path = run_folder / V1516_TASKS_NAME
    increment_name = str(report.get('increment_file') or '').strip()
    if not increment_name or Path(increment_name).name != increment_name:
        raise RuntimeError(f'v1.5.16報告的增量檔名無效：{increment_name!r}')
    increment_path = run_folder / increment_name
    if not increment_path.is_file():
        raise FileNotFoundError(f'v1.5.16報告指定的標準化增量不存在：{increment_path}')

    with task_path.open('r', encoding='utf-8-sig', newline='') as f:
        reader = csv.DictReader(f)
        task_fields = set(reader.fieldnames or [])
        required = {'trade_date', 'market', 'api_status', 'rows', 'error'}
        if not required.issubset(task_fields):
            raise RuntimeError(f'v1.5.16補查結果缺欄位：{sorted(required - task_fields)}')
        tasks = list(reader)

    task_counts = {}
    task_market_totals = {'TWSE': 0, 'TPEX': 0}
    for row in tasks:
        day = parse_date(row.get('trade_date'))
        market = parse_market(row.get('market'))
        key = (day, market)
        status = str(row.get('api_status') or '').strip().upper()
        try:
            count = int(float(str(row.get('rows') or '').replace(',', '').strip()))
        except Exception:
            count = -1
        error = str(row.get('error') or '').strip()
        if day is None or market not in {'TWSE', 'TPEX'}:
            raise RuntimeError(f'v1.5.16補查結果有無效市場日：{row}')
        if key in task_counts:
            raise RuntimeError(f'v1.5.16補查結果有重複市場日：{key}')
        if status != 'PASS' or count <= 0 or error:
            raise RuntimeError(f'v1.5.16補查任務未通過：{key} status={status} rows={count} error={error}')
        task_counts[key] = count
        task_market_totals[market] += count

    expected_backfill_rows = int(report.get('backfill_rows', -1))
    if expected_backfill_rows < 0 or sum(task_counts.values()) != expected_backfill_rows:
        raise RuntimeError(
            'v1.5.16補查結果列數與報告 backfill_rows 不一致：'
            f'tasks={sum(task_counts.values())} report={expected_backfill_rows}'
        )
    reported_by_market = report.get('backfill_by_market') or {}
    for market in ('TWSE', 'TPEX'):
        if int(reported_by_market.get(market, -1)) != task_market_totals[market]:
            raise RuntimeError(
                f'v1.5.16 {market}補查列數與 backfill_by_market 不一致：'
                f'tasks={task_market_totals[market]} report={reported_by_market.get(market)}'
            )
    task_dates = sorted({day for day, _ in task_counts})
    if task_dates != sorted(str(x) for x in (report.get('backfill_trade_dates') or [])):
        raise RuntimeError(
            f'v1.5.16補查日期與報告不一致：tasks={task_dates} '
            f'report={report.get("backfill_trade_dates")}'
        )

    headers, rows = _iter_source_csv_rows(increment_path)
    increment_groups = defaultdict(list)
    for row in rows:
        normalized = _normalize_source_record(row, headers, increment_path)
        if normalized is None:
            raise RuntimeError(f'v1.5.16標準化增量含無法正規化資料列：{increment_path}')
        increment_groups[(normalized['date'], normalized['market'])].append(normalized)
    actual_counts = {key: len(group) for key, group in increment_groups.items()}
    if actual_counts != task_counts:
        raise RuntimeError(
            'v1.5.16補查結果 CSV 與標準化增量逐市場日列數不一致：'
            f'tasks={{{", ".join(f"{k}:{v}" for k,v in sorted(task_counts.items()))}}} '
            f'increment={{{", ".join(f"{k}:{v}" for k,v in sorted(actual_counts.items()))}}}'
        )
    for key, group in increment_groups.items():
        keys = [(r['date'], r['market'], r['code']) for r in group]
        if len(keys) != len(set(keys)):
            raise RuntimeError(f'v1.5.16標準化增量存在重複自然鍵：{key}')
    if sum(actual_counts.values()) != expected_backfill_rows:
        raise RuntimeError('v1.5.16標準化增量總列數與報告不一致。')

    return task_counts, {
        'task_file': str(task_path),
        'increment_file': str(increment_path),
        'task_market_day_count': len(task_counts),
        'task_rows_total': sum(task_counts.values()),
        'increment_market_day_count': len(actual_counts),
        'increment_rows_total': sum(actual_counts.values()),
        'market_rows': task_market_totals,
        'status': 'PASS',
    }


def _read_v1516_calendar(path: Path, run_folder: Path, report: dict) -> tuple[list[dict], dict]:
    task_counts, backfill_audit = _read_v1516_backfill_evidence(run_folder, report)
    with path.open('r', encoding='utf-8-sig', newline='') as f:
        reader = csv.DictReader(f)
        fields = set(reader.fieldnames or [])
        required = {'trade_date', 'market', 'calendar_expected_open', 'database_rows_before'}
        if not required.issubset(fields):
            raise RuntimeError(f'v1.5.16官方日曆缺欄位：{sorted(required - fields)}')
        rows = list(reader)
    start = parse_date((report.get('check_window') or {}).get('start'))
    end = parse_date((report.get('check_window') or {}).get('end'))
    if not start or not end or start > end:
        raise RuntimeError('v1.5.16報告的檢查區間無效。')
    expected = []
    seen = set()
    calendar_open = set()
    for row in rows:
        day = parse_date(row.get('trade_date'))
        market = parse_market(row.get('market'))
        flag = str(row.get('calendar_expected_open', '')).strip().lower()
        is_open = flag in {'true', '1', 'yes', 'y'}
        if not day or market not in {'TWSE', 'TPEX'} or not (start <= day <= end):
            raise RuntimeError(f'v1.5.16日曆有無效日期／市場列：{row}')
        key = (day, market)
        if key in seen:
            raise RuntimeError(f'v1.5.16日曆出現重複市場日：{key}')
        seen.add(key)
        if is_open:
            calendar_open.add(key)
            count_text = str(row.get('database_rows_before') or '').replace(',', '').strip()
            try:
                count = int(float(count_text))
            except Exception:
                count = -1
            if count > 0:
                if key in task_counts:
                    raise RuntimeError(f'v1.5.16資料庫原已有資料卻又列為全日補抓任務：{key}')
                expected_count = count
                basis = 'V1_5_16_DATABASE_ROWS_BEFORE'
            elif count == 0 and key in task_counts:
                expected_count = int(task_counts[key])
                basis = 'V1_5_16_VERIFIED_API_BACKFILL_AND_INCREMENT'
            else:
                raise RuntimeError(
                    f'v1.5.16官方日曆預期開市，但既有資料列數為{count_text!r}且無對應通過的補抓證據：{key}'
                )
            expected.append({
                'date': day, 'market': market, 'expected_rows': expected_count,
                'calendar_database_rows_before': count,
                'expected_rows_basis': basis,
                'calendar_evidence': row.get('calendar_evidence', ''),
                'api_backfill_status': row.get('api_backfill_status', ''),
            })
        elif key in task_counts:
            raise RuntimeError(f'官方日曆判定休市，卻存在該日補抓任務：{key}')
    unexpected_tasks = set(task_counts) - calendar_open
    if unexpected_tasks:
        raise RuntimeError(f'v1.5.16補抓任務不在官方預期開市日內：{sorted(unexpected_tasks)}')
    if len(expected) != int(report.get('expected_market_days', -1)):
        raise RuntimeError(
            f'v1.5.16日曆預期市場日數與報告不符：{len(expected)} / '
            f'{report.get("expected_market_days")}'
        )
    if len(expected) != int(report.get('expected_session_dates', -1)) * 2:
        raise RuntimeError('v1.5.16官方預期交易日與雙市場列數不一致。')
    window = report.get('check_window') or {}
    return expected, {
        'start': start, 'end': end, 'calendar_rows': len(rows),
        'expected_market_days': len(expected),
        'expected_sessions': int(report.get('expected_session_dates', 0)),
        'same_day_included': bool(window.get('same_day_included')),
        'same_day_gate_hour_taipei': window.get('same_day_gate_hour_taipei'),
        'backfill_evidence': backfill_audit,
    }


def _apply_v159_pinned_calendar_row_counts(rows: list[dict]) -> tuple[list[dict], list[dict]]:
    """For 2026-11-11, use sealed v1.5.9 full-day correction counts, not the
    possibly inflated database_rows_before count in the rolling coverage calendar.

    The override is narrowly scoped to the exact two market-days whose correction
    files, ZIP/manifest and canonical records are pinned elsewhere in this script.
    It is not a general relaxation of daily row-count validation.
    """
    pinned = {
        ('2026-11-11', 'TWSE'): int(V159_EXPECTED_TWSE_ROWS),
        ('2026-11-11', 'TPEX'): int(V159_EXPECTED_TPEX_ROWS),
    }
    copied = []
    seen = set()
    audit = []
    for original in rows:
        item = dict(original)
        day = str(item.get('date') or '')
        market = str(item.get('market') or '')
        key = (day, market)
        if key in seen:
            raise RuntimeError(f'日曆列數覆寫前出現重複市場日：{key}')
        seen.add(key)
        raw_count = int(item.get('expected_rows', -1))
        item['calendar_database_rows_before'] = raw_count
        if key in pinned:
            exact = pinned[key]
            item['expected_rows'] = exact
            item['expected_rows_basis'] = 'PINNED_V1_5_9_SEALED_FULL_DAY_CORRECTION'
            item['calendar_count_override'] = raw_count != exact
            audit.append({
                'date': day, 'market': market,
                'database_rows_before': raw_count,
                'pinned_correction_rows': exact,
                'overridden': raw_count != exact,
                'basis': 'V1_5_9_ZIP_MANIFEST_FILE_SHA_AND_CANONICAL_SHA',
            })
        else:
            item['expected_rows_basis'] = 'V1_5_16_DATABASE_ROWS_BEFORE'
            item['calendar_count_override'] = False
        copied.append(item)

    present = {key for key in seen if key[0] == '2026-11-11'}
    expected_present = set(pinned).intersection({key for key in seen if key[0] == '2026-11-11'})
    if present and expected_present != set(pinned):
        raise RuntimeError(
            'v1.5.16官方日曆只包含2026-11-11其中一個市場；'
            f'預期雙市場都存在，實際={sorted(present)}'
        )
    return copied, audit


def _iter_source_csv_rows(path: Path):
    last_error = None
    for encoding in ('utf-8-sig', 'utf-8', 'cp950', 'big5'):
        try:
            with path.open('r', encoding=encoding, newline='') as f:
                reader = csv.DictReader(f)
                headers = list(reader.fieldnames or [])
                if not headers:
                    return [], []
                return headers, list(reader)
        except UnicodeDecodeError as exc:
            last_error = exc
    raise RuntimeError(f'無法解碼行情來源CSV：{path}；{last_error}')


def _normalize_source_record(row: dict, headers: list[str], path: Path):
    date_col = find_col(headers, ALIASES['date'])
    market_col = find_col(headers, ALIASES['market'])
    code_col = find_col(headers, ALIASES['code'])
    if not all((date_col, market_col, code_col)):
        return None
    day = parse_date(row.get(date_col))
    market = parse_market(row.get(market_col))
    code = norm_full_pool_code(row.get(code_col))
    if not day or market not in {'TWSE', 'TPEX'} or not code:
        return None
    name_col = find_col(headers, ALIASES['name'])
    value_cols = {k: find_col(headers, ALIASES[k]) for k in ('open', 'high', 'low', 'close', 'volume')}
    if any(not value_cols[k] for k in value_cols):
        raise RuntimeError(f'行情來源缺少必要OHLCV欄位：{path}；{value_cols}')
    change_col = find_col(headers, ['price_change', '漲跌價差', '漲跌'])
    source_col = find_col(headers, ['source', '資料源', '資料來源', '來源'])
    def normalized_num(col):
        value = num(row.get(col))
        if value is None:
            return None
        return int(value) if col == value_cols['volume'] and float(value).is_integer() else float(value)
    return {
        'date': day, 'market': market, 'code': code,
        'name': str(row.get(name_col) or '').strip() if name_col else '',
        'open': num(row.get(value_cols['open'])),
        'high': num(row.get(value_cols['high'])),
        'low': num(row.get(value_cols['low'])),
        'close': num(row.get(value_cols['close'])),
        'volume': num(row.get(value_cols['volume'])),
        'change': num(row.get(change_col)) if change_col else None,
        'source': str(row.get(source_col) or '').strip() if source_col else '',
        '_source_file': str(path),
    }


def _candidate_group_signature(records: list[dict]) -> tuple:
    return tuple(sorted(((r['code'], r['open'], r['high'], r['low'], r['close'], r['volume']) for r in records), key=lambda x: x[0]))


def _validate_adapter_day(group: list[dict], expected_rows: int, market: str, day: str, source: str):
    if len(group) != expected_rows:
        raise RuntimeError(f'{market} {day}列數不符：{len(group)}/{expected_rows}；來源={source}')
    keys = [(r['date'], r['market'], r['code']) for r in group]
    if len(keys) != len(set(keys)):
        raise RuntimeError(f'{market} {day}存在重複自然鍵；來源={source}')
    zero_volume = 0
    missing_ohlc = 0
    invalid_ohlc = 0
    for r in group:
        if r['volume'] is None or r['volume'] < 0:
            raise RuntimeError(f'{market} {day}成交量缺值或負值：{r["code"]}；來源={source}')
        if r['volume'] == 0:
            zero_volume += 1
        vals = [r[x] for x in ('open', 'high', 'low', 'close')]
        if any(x is None for x in vals):
            missing_ohlc += 1
            continue
        o, h, l, c = vals
        if min(vals) <= 0 or h < l or h + 1e-9 < max(o, c) or l - 1e-9 > min(o, c):
            invalid_ohlc += 1
    zero_ratio = zero_volume / len(group)
    missing_ratio = missing_ohlc / len(group)
    if zero_ratio > 0.25 or missing_ratio > 0.25 or invalid_ohlc:
        raise RuntimeError(
            f'{market} {day}品質不通過：zero_volume={zero_ratio:.2%}、'
            f'missing_ohlc={missing_ratio:.2%}、invalid_ohlc={invalid_ohlc}；來源={source}'
        )


V159_CANONICAL_ALIASES = {
    'trade_date': ['trade_date', 'date', '日期', '交易日期', '資料日期', '年月日'],
    'market': ['market', '市場', '市場別', '交易市場'],
    'instrument_code': ['instrument_code', 'code', 'stock_id', 'stock_code', '證券代號', '證券代碼', '代號', '股票代號'],
    'instrument_name': ['instrument_name', 'name', 'stock_name', '證券名稱', '名稱', '股票名稱'],
    'open': ['open', 'opening_price', 'open_price', '開盤', '開盤價', '開盤價格'],
    'high': ['high', 'highest_price', 'high_price', '最高', '最高價', '最高價格'],
    'low': ['low', 'lowest_price', 'low_price', '最低', '最低價', '最低價格'],
    'close': ['close', 'closing_price', 'close_price', '收盤', '收盤價', '收盤價格'],
    'volume': ['volume', 'trade_volume', 'trading_volume', '成交股數', '成交量'],
    'trade_value': ['trade_value', 'traded_value', 'turnover', 'amount', '成交金額', '成交金額元', '成交金額(元)'],
    'price_change': ['price_change', 'change', '漲跌', '漲跌價差'],
    'transactions': ['transactions', 'transaction_count', 'transaction', '成交筆數', '筆數', '交易筆數'],
    'source': ['source', 'source_archive_member', '來源', '資料來源'],
}


def _normalize_v159_canonical_record(row: dict, headers: list[str], expected_market: str, source_path: Path) -> dict:
    """Mirror v1.5.10 normalize_csv_rows/normalize_value without SSO pool-code rewriting."""
    mapping = {field: find_col(headers, aliases) for field, aliases in V159_CANONICAL_ALIASES.items()}
    required = ('trade_date', 'market', 'instrument_code', 'open', 'high', 'low', 'close', 'volume')
    missing = [field for field in required if not mapping.get(field)]
    if missing:
        raise RuntimeError(f'H5備援CSV無法重建v1.5.10 canonical欄位：{missing}；{source_path}')

    day = parse_date(row.get(mapping['trade_date']))
    market = parse_market(row.get(mapping['market']))
    code = str(row.get(mapping['instrument_code']) or '').strip()
    if not day or market != expected_market or not code:
        raise RuntimeError(f'H5備援canonical列日期／市場／原始代號不符：{day}/{market}/{code}')

    record = {
        'trade_date': day,
        'market': market,
        # v1.5.10 canonical code is only strip(); do not apply norm_full_pool_code here.
        'instrument_code': code,
        'instrument_name': str(row.get(mapping['instrument_name']) or '').strip() if mapping.get('instrument_name') else '',
        'source': str(row.get(mapping['source']) or '').strip() if mapping.get('source') else '',
    }
    integer_fields = {'volume', 'trade_value', 'transactions'}
    numeric_fields = {'open', 'high', 'low', 'close', 'volume', 'trade_value', 'price_change', 'transactions'}
    for field in numeric_fields:
        col = mapping.get(field)
        value = num(row.get(col)) if col else None
        if value is not None and field in integer_fields:
            value = int(round(value))
        record[field] = value
    return record


def _v159_canonical_sha256(records: list[dict]) -> str:
    """Reproduce v1.5.10 canonical_records_sha256 over already normalized records."""
    fields = ('trade_date', 'market', 'instrument_code', 'instrument_name',
              'open', 'high', 'low', 'close', 'volume', 'trade_value',
              'price_change', 'transactions', 'source')
    integer_fields = {'volume', 'trade_value', 'transactions'}
    ordered = []
    for record in records:
        row = {}
        for field in fields:
            value = record.get(field)
            if field == 'trade_date':
                parsed = parse_date(value)
                row[field] = parsed if isinstance(parsed, str) else (parsed.isoformat() if parsed else '')
            elif field == 'market':
                row[field] = parse_market(value)
            elif field == 'instrument_code':
                row[field] = str(value or '').strip()
            elif field in {'open', 'high', 'low', 'close', 'volume', 'trade_value', 'price_change', 'transactions'}:
                number = num(value)
                if number is not None and field in integer_fields:
                    number = int(round(number))
                row[field] = number
            else:
                row[field] = str(value or '').strip()
        ordered.append(row)
    ordered.sort(key=lambda x: (x['trade_date'], x['market'], x['instrument_code']))
    payload = json.dumps(ordered, ensure_ascii=False, sort_keys=True,
                         separators=(',', ':'), default=str).encode('utf-8')
    return hashlib.sha256(payload).hexdigest()


def _read_h5_v159_snapshot_archive(zip_path: Path, work_dir: Path,
                                   expected_zip_sha256: str) -> dict:
    """Validate the archived H5 snapshot as a narrowly-scoped v1.5.9 fallback.

    The H5 run may be PARTIAL_BLOCKED solely because one of 848 candidate price
    pairs is incomplete. This fallback is allowed only when both 11/11 market
    days, both correction checks, the pinned v1.5.9 archive/manifest/file hashes,
    and the per-market canonical correction hashes all independently pass.
    It does not claim the H5 candidate price-pair audit was downstream-ready.
    """
    import zipfile
    actual_zip_sha = _file_sha256(zip_path)
    if actual_zip_sha != expected_zip_sha256:
        raise RuntimeError(f'H5備援ZIP SHA256不符：{actual_zip_sha}')
    with zipfile.ZipFile(zip_path, 'r') as zf:
        bad = zf.testzip()
        if bad:
            raise RuntimeError(f'H5備援ZIP CRC失敗：{bad}')
        names = zf.namelist()
        report_members = [n for n in names if n.rsplit('/', 1)[-1] == H5_V159_BACKUP_REPORT]
        csv_members = [n for n in names if n.rsplit('/', 1)[-1] == H5_V159_BACKUP_MARKET_CSV]
        if len(report_members) != 1 or len(csv_members) != 1:
            raise RuntimeError('H5備援ZIP必要報告／行情CSV成員不是各一份。')
        report = json.loads(zf.read(report_members[0]).decode('utf-8-sig'))
        csv_bytes = zf.read(csv_members[0])

    if report.get('version') != 'SSO_H5_848_Official_Price_Backfill_v1.0.2':
        raise RuntimeError(f'H5備援報告版本不符：{report.get("version")}')
    if int(report.get('candidate_count', -1)) != 848 or report.get('candidate_sha256') != H5_V159_BACKUP_CANDIDATE_SHA256:
        raise RuntimeError('H5備援報告的848檔凍結候選指紋不符。')

    source = report.get('v159_correction_source') or {}
    expected_source = {
        'source_zip_sha256': V159_EXPECTED_ZIP_SHA256,
        'source_manifest_sha256': V159_EXPECTED_MANIFEST_SHA256,
        'twse_rows': V159_EXPECTED_TWSE_ROWS,
        'twse_file_sha256': V159_EXPECTED_TWSE_FILE_SHA256,
        'tpex_rows': V159_EXPECTED_TPEX_ROWS,
        'tpex_file_sha256': V159_EXPECTED_TPEX_FILE_SHA256,
    }
    for key, expected in expected_source.items():
        if source.get(key) != expected:
            raise RuntimeError(f'H5備援所記錄的v1.5.9證據不符：{key}={source.get(key)!r}')

    correction = report.get('correction_validation') or {}
    for market in ('TWSE', 'TPEX'):
        if (correction.get(market) or {}).get('status') != 'PASS':
            raise RuntimeError(f'H5備援的v1.5.9 {market}修正核驗不是PASS。')
    integration = report.get('integration_policy') or {}
    if integration.get('2026_11_11_correction_layer_checked_and_applied') is not True:
        raise RuntimeError('H5備援報告未確認已套用2026-11-11修正層。')

    counts = report.get('counts') or {}
    if (int(counts.get('expected_market_days', -1)) != 12 or
        int(counts.get('passed_market_days', -1)) != 12 or
        int(counts.get('all_market_rows', -1)) != 14452):
        raise RuntimeError(f'H5備援六日雙市場覆蓋不完整：{counts}')
    failures = report.get('api_failures') or []
    if failures:
        raise RuntimeError(f'H5備援六日官方API存在失敗：{failures[:5]}')

    daily = report.get('daily_summary') or []
    daily_map = {(str(x.get('trade_date')), parse_market(x.get('market'))): x for x in daily}
    expected_daily = {
        ('2026-11-11', 'TWSE'): V159_EXPECTED_TWSE_ROWS,
        ('2026-11-11', 'TPEX'): V159_EXPECTED_TPEX_ROWS,
    }
    for key, expected_rows in expected_daily.items():
        item = daily_map.get(key)
        if not item or str(item.get('status', '')).upper() != 'PASS' or int(item.get('rows', -1)) != expected_rows:
            raise RuntimeError(f'H5備援11/11逐市場日報告不符：{key}；實際={item}')

    sources = report.get('data_sources') or {}
    tpex_sources = ' '.join(str(v) for k, v in sources.items() if str(k).upper().startswith('TPEX'))
    if 'type=EW' not in tpex_sources and 'se=EW' not in tpex_sources:
        raise RuntimeError('H5備援報告未能證明TPEx採用type=EW來源。')

    roundtrip = report.get('standardized_csv_roundtrip') or {}
    csv_sha = hashlib.sha256(csv_bytes).hexdigest()
    if roundtrip.get('status') != 'PASS' or roundtrip.get('file_sha256') != csv_sha or int(roundtrip.get('rows', -1)) != 14452:
        raise RuntimeError('H5備援標準化CSV未通過報告內SHA／列數round-trip。')

    extract_dir = Path(work_dir) / 'trusted_h5_v159_backup'
    extract_dir.mkdir(parents=True, exist_ok=False)
    csv_path = extract_dir / H5_V159_BACKUP_MARKET_CSV
    csv_path.write_bytes(csv_bytes)
    headers, rows = _iter_source_csv_rows(csv_path)
    groups = defaultdict(list)
    canonical_groups = defaultdict(list)
    for row in rows:
        normalized = _normalize_source_record(row, headers, csv_path)
        if normalized is None or normalized['date'] != '2026-11-11':
            continue
        groups[normalized['market']].append(normalized)
        # Canonical hash is rebuilt from the untouched CSV fields, preserving
        # exact instrument-code identity and all v1.5.10 canonical fields.
        canonical_groups[normalized['market']].append(
            _normalize_v159_canonical_record(row, headers, normalized['market'], csv_path)
        )

    expected_canonical = {
        'TWSE': V159_EXPECTED_TWSE_CANONICAL_SHA256,
        'TPEX': V159_EXPECTED_TPEX_CANONICAL_SHA256,
    }
    expected_rows = {'TWSE': V159_EXPECTED_TWSE_ROWS, 'TPEX': V159_EXPECTED_TPEX_ROWS}
    trusted = {}
    for market in ('TWSE', 'TPEX'):
        group = groups.get(market, [])
        _validate_adapter_day(group, expected_rows[market], market, '2026-11-11', str(zip_path))
        canonical = _v159_canonical_sha256(canonical_groups.get(market, []))
        if market == 'TPEX' and any('type_EW' not in str(r.get('source', '')) for r in canonical_groups.get(market, [])):
            raise RuntimeError('H5備援TPEx canonical資料列未全部保留type=EW來源標記。')
        if canonical != expected_canonical[market]:
            raise RuntimeError(f'H5備援{market} 2026-11-11 canonical SHA不符：{canonical}')
        trusted[market] = group

    return {
        'zip_path': str(zip_path), 'zip_sha256': actual_zip_sha,
        'report_member': report_members[0], 'csv_member': csv_members[0],
        'csv_path': str(csv_path), 'csv_sha256': csv_sha,
        'source_v159_zip_sha256': source.get('source_zip_sha256'),
        'source_v159_manifest_sha256': source.get('source_manifest_sha256'),
        'canonical_sha256_by_market': expected_canonical,
        'records_by_market': trusted,
        'trusted_basis': 'PINNED_H5_ZIP_SHA + PINNED_V159_ZIP/MANIFEST/CSV_SHA + 11_11_DAILY_COUNTS + V159_CANONICAL_SHA',
        'h5_candidate_price_pair_downstream_ready': bool(report.get('downstream_ready')),
        'h5_candidate_price_pairs': (report.get('candidate_price_pairs') or {}).get('price_pair_ready'),
    }


def _load_h5_v159_snapshot_backup(work_dir: Path) -> dict | None:
    """Locate only the exact H5 v1.0.2 archive whose complete ZIP hash is pinned."""
    matches = []
    for folder in PROJECT.glob(H5_V159_BACKUP_FOLDER_PREFIX + '*'):
        if not folder.is_dir():
            continue
        for zip_path in folder.glob('*.zip'):
            try:
                if _file_sha256(zip_path) == H5_V159_BACKUP_ZIP_SHA256:
                    matches.append((folder.stat().st_mtime_ns, folder.name, zip_path))
            except OSError:
                continue
    if not matches:
        return None
    _, _, zip_path = max(matches, key=lambda x: (x[0], x[1], str(x[2])))
    return _read_h5_v159_snapshot_archive(zip_path, work_dir, H5_V159_BACKUP_ZIP_SHA256)


def test_h5_v159_backup_canonical_contract():
    """Offline deterministic tests for canonical hashing and full H5 archive validation."""
    import io, zipfile
    global V159_EXPECTED_ZIP_SHA256, V159_EXPECTED_MANIFEST_SHA256
    global V159_EXPECTED_TWSE_FILE_SHA256, V159_EXPECTED_TPEX_FILE_SHA256
    global V159_EXPECTED_TWSE_CANONICAL_SHA256, V159_EXPECTED_TPEX_CANONICAL_SHA256
    global V159_EXPECTED_TWSE_ROWS, V159_EXPECTED_TPEX_ROWS, H5_V159_BACKUP_CANDIDATE_SHA256

    with tempfile.TemporaryDirectory(prefix='sso_v513_v159_canonical_') as td:
        records = []
        for market, prefix, n in (('TWSE', 'T', 1390), ('TPEX', 'P', 1020)):
            for i in range(n):
                records.append({
                    'trade_date': '2026-11-11', 'market': market,
                    'instrument_code': f'{prefix}{i:04d}', 'instrument_name': f'TEST{i}',
                    'open': 10.0, 'high': 11.0, 'low': 9.0, 'close': 10.5,
                    'volume': 1000, 'trade_value': 10500, 'price_change': 0.5,
                    'transactions': 10, 'source': 'UNIT_TEST_type_EW',
                })
        digest = _v159_canonical_sha256(records)
        if len(digest) != 64 or digest != _v159_canonical_sha256(list(reversed(records))):
            raise AssertionError('v1.5.9 canonical SHA determinism failed')
        sample_headers = ['日期', '市場', '證券代號', '證券名稱', '開盤價', '最高價', '最低價', '收盤價', '成交股數', '成交金額', '漲跌價差', '成交筆數', '資料來源']
        sample = {'日期': '115/11/11', '市場': '上櫃', '證券代號': '00411A', '證券名稱': '測試',
                  '開盤價': '10', '最高價': '11', '最低價': '9', '收盤價': '10.5', '成交股數': '1000',
                  '成交金額': '10500', '漲跌價差': '-', '成交筆數': '10', '資料來源': 'type_EW'}
        canonical_sample = _normalize_v159_canonical_record(sample, sample_headers, 'TPEX', Path('synthetic.csv'))
        if canonical_sample['instrument_code'] != '00411A' or canonical_sample['trade_value'] != 10500 or canonical_sample['transactions'] != 10 or canonical_sample['price_change'] is not None:
            raise AssertionError('v1.5.9 canonical normalization lost full-code / optional numeric fields')
        altered = [dict(x) for x in records]
        altered[0]['close'] = 10.6
        if _v159_canonical_sha256(altered) == digest:
            raise AssertionError('v1.5.9 canonical SHA failed to detect changed OHLC')

        # Exercise the entire sealed-snapshot reader with a synthetic 6-day archive.
        old = {name: globals()[name] for name in (
            'V159_EXPECTED_ZIP_SHA256', 'V159_EXPECTED_MANIFEST_SHA256',
            'V159_EXPECTED_TWSE_FILE_SHA256', 'V159_EXPECTED_TPEX_FILE_SHA256',
            'V159_EXPECTED_TWSE_CANONICAL_SHA256', 'V159_EXPECTED_TPEX_CANONICAL_SHA256',
            'V159_EXPECTED_TWSE_ROWS', 'V159_EXPECTED_TPEX_ROWS', 'H5_V159_BACKUP_CANDIDATE_SHA256')}
        try:
            V159_EXPECTED_ZIP_SHA256 = 'b' * 64
            V159_EXPECTED_MANIFEST_SHA256 = 'c' * 64
            V159_EXPECTED_TWSE_FILE_SHA256 = 'd' * 64
            V159_EXPECTED_TPEX_FILE_SHA256 = 'e' * 64
            V159_EXPECTED_TWSE_CANONICAL_SHA256 = _v159_canonical_sha256(records[:1390])
            V159_EXPECTED_TPEX_CANONICAL_SHA256 = _v159_canonical_sha256(records[1390:])
            V159_EXPECTED_TWSE_ROWS, V159_EXPECTED_TPEX_ROWS = 1390, 1020
            H5_V159_BACKUP_CANDIDATE_SHA256 = 'a' * 64

            counts_by_day = {
                '2026-11-06': {'TWSE': 1389, 'TPEX': 1017},
                '2026-11-09': {'TWSE': 1389, 'TPEX': 1020},
                '2026-11-10': {'TWSE': 1389, 'TPEX': 1020},
                '2026-11-11': {'TWSE': 1390, 'TPEX': 1020},
                '2026-11-12': {'TWSE': 1389, 'TPEX': 1020},
                '2026-11-13': {'TWSE': 1389, 'TPEX': 1020},
            }
            columns = ['trade_date', 'market', 'instrument_code', 'instrument_name', 'open', 'high', 'low', 'close', 'volume', 'trade_value', 'price_change', 'transactions', 'source']
            stream = io.StringIO(newline='')
            writer = csv.DictWriter(stream, fieldnames=columns)
            writer.writeheader()
            daily_rows = []
            for day, markets in counts_by_day.items():
                for market, n in markets.items():
                    daily_rows.append({'trade_date': day, 'market': market, 'rows': n, 'status': 'PASS'})
                    for j in range(n):
                        market_prefix = 'T' if market == 'TWSE' else 'P'
                        writer.writerow({
                            'trade_date': day, 'market': market,
                            'instrument_code': f'{market_prefix}{j:04d}',
                            'instrument_name': f'TEST{j}', 'open': '10', 'high': '11', 'low': '9', 'close': '10.5',
                            'volume': '1000', 'trade_value': '10500', 'price_change': '0.5', 'transactions': '10',
                            'source': 'UNIT_TEST_type_EW',
                        })
            csv_bytes = ('\ufeff' + stream.getvalue()).encode('utf-8')
            fake_report = {
                'version': 'SSO_H5_848_Official_Price_Backfill_v1.0.2',
                'candidate_count': 848, 'candidate_sha256': H5_V159_BACKUP_CANDIDATE_SHA256,
                'v159_correction_source': {
                    'source_zip_sha256': V159_EXPECTED_ZIP_SHA256,
                    'source_manifest_sha256': V159_EXPECTED_MANIFEST_SHA256,
                    'twse_rows': 1390, 'twse_file_sha256': V159_EXPECTED_TWSE_FILE_SHA256,
                    'tpex_rows': 1020, 'tpex_file_sha256': V159_EXPECTED_TPEX_FILE_SHA256,
                },
                'correction_validation': {'TWSE': {'status': 'PASS'}, 'TPEX': {'status': 'PASS'}},
                'integration_policy': {'2026_11_11_correction_layer_checked_and_applied': True},
                'counts': {'expected_market_days': 12, 'passed_market_days': 12, 'all_market_rows': 14452},
                'api_failures': [], 'daily_summary': daily_rows,
                'data_sources': {'TWSE': 'MI_INDEX', 'TPEX_modern': 'https://example.invalid/otc?type=EW'},
                'standardized_csv_roundtrip': {'status': 'PASS', 'file_sha256': hashlib.sha256(csv_bytes).hexdigest(), 'rows': 14452},
                'downstream_ready': False,
                'candidate_price_pairs': {'price_pair_ready': 847},
            }
            backup_zip = Path(td) / 'synthetic_h5_backup.zip'
            with zipfile.ZipFile(backup_zip, 'w', compression=zipfile.ZIP_DEFLATED) as zf:
                zf.writestr('snapshot/' + H5_V159_BACKUP_REPORT, json.dumps(fake_report, ensure_ascii=False).encode('utf-8'))
                zf.writestr('snapshot/' + H5_V159_BACKUP_MARKET_CSV, csv_bytes)
            archive_sha = _file_sha256(backup_zip)
            checked = _read_h5_v159_snapshot_archive(backup_zip, Path(td), archive_sha)
            if len(checked['records_by_market']['TWSE']) != 1390 or len(checked['records_by_market']['TPEX']) != 1020:
                raise AssertionError('H5 archive validator returned unexpected 11/11 correction rows')
            if checked['h5_candidate_price_pair_downstream_ready'] is not False or checked['h5_candidate_price_pairs'] != 847:
                raise AssertionError('H5 archive validator incorrectly conflated price-pair completeness with correction trust')
        finally:
            globals().update(old)

    return {'canonical_sha_deterministic': 'PASS', 'ohlc_mutation_detected': 'PASS',
            'full_code_identity_and_optional_fields': 'PASS',
            'sealed_h5_archive_contract': 'PASS', 'partial_price_pair_does_not_invalidate_correction': 'PASS'}


def build_v1516_append_adapter(work_dir: Path) -> dict:
    """Build a temporary legacy-compatible delta from v1.5.x verified increments."""
    global MARKET_STATE_DIR, DELTA_PATH, STATE_PATH
    run_folder, report = _latest_v1516_run(MARKET_DATA_ROOT)
    calendar_file = run_folder / V1516_CALENDAR_NAME
    expected_rows, calendar_meta = _read_v1516_calendar(calendar_file, run_folder, report)
    post_cutoff = [x for x in expected_rows if x['date'] > V1516_HISTORICAL_CUTOFF]
    post_cutoff, v159_calendar_count_audit = _apply_v159_pinned_calendar_row_counts(post_cutoff)
    calendar_meta['v159_pinned_row_count_overrides'] = v159_calendar_count_audit
    for item in v159_calendar_count_audit:
        if item['overridden']:
            log('[V159 CALENDAR COUNT OVERRIDE] ' + json.dumps(item, ensure_ascii=False))
    if not post_cutoff:
        raise RuntimeError('v1.5.16官方日曆沒有2026-10-28之後的預期市場日；拒絕產生空增量。')
    expected_map = {(x['date'], x['market']): x for x in post_cutoff}

    # Read only official standardized increments and whole-day correction files.
    source_files = set()
    for version_dir in MARKET_DATA_ROOT.glob('v1.5.*_*'):
        if not version_dir.is_dir():
            continue
        source_files.update(version_dir.rglob('全市場標準化增量_*.csv'))
        source_files.update(version_dir.rglob('修正_TWSE_*.csv'))
        source_files.update(version_dir.rglob('修正_TPEX_*.csv'))
    source_files = sorted((p for p in source_files if p.is_file()), key=lambda p: (p.stat().st_mtime_ns, str(p)))
    if not source_files:
        raise FileNotFoundError('找不到既有 v1.5.x 標準化增量／全日修正 CSV。')

    candidates = defaultdict(list)
    scan_audit = []
    for path in source_files:
        headers, rows = _iter_source_csv_rows(path)
        date_col = find_col(headers, ALIASES['date'])
        market_col = find_col(headers, ALIASES['market'])
        code_col = find_col(headers, ALIASES['code'])
        if not all((date_col, market_col, code_col)):
            scan_audit.append({'path': str(path), 'status': 'SKIP_SCHEMA'})
            continue
        local = defaultdict(list)
        for row in rows:
            day = parse_date(row.get(date_col))
            market = parse_market(row.get(market_col))
            if not day or market not in {'TWSE', 'TPEX'}:
                continue
            key = (day, market)
            if (day, market) not in expected_map:
                continue
            normalized = _normalize_source_record(row, headers, path)
            if normalized is not None:
                local[key].append(normalized)
        for (day, market), group in local.items():
            key = (day, market)
            expected_count = expected_map[key]['expected_rows']
            if len(group) != expected_count:
                continue
            correction = path.name.startswith(f'修正_{market}_')
            verified_correction = False
            if key == ('2026-11-11', 'TWSE') and correction:
                verified_correction = _file_sha256(path) == V1516_EXPECTED_TWSE_1111_SHA256
            elif key == ('2026-11-11', 'TPEX') and correction:
                verified_correction = _file_sha256(path) == V1516_EXPECTED_TPEX_1111_SHA256
            # Exact-key duplicate check within each source file.
            gkeys = [(r['date'], r['market'], r['code']) for r in group]
            if len(gkeys) != len(set(gkeys)):
                raise RuntimeError(f'來源檔單一市場日出現重複自然鍵：{path} {key}')
            candidates[key].append({
                'path': path, 'records': group, 'correction': correction,
                'verified_correction': verified_correction,
                'file_sha256': _file_sha256(path),
                'signature': _candidate_group_signature(group),
            })
        scan_audit.append({'path': str(path), 'status': 'SCANNED', 'rows': len(rows),
                           'candidate_market_days': len(local), 'bytes': path.stat().st_size})

    # A previous H5 run independently loaded the sealed v1.5.9 ZIP/manifest,
    # applied both 11/11 corrections, and retained its entire six-day snapshot.
    # Use this exact fixed-SHA snapshot only when the raw correction CSV is no
    # longer discoverable in v1.5.x folders; never infer trust from row counts alone.
    h5_backup_info = None
    if any(not any(x['verified_correction'] for x in candidates.get(("2026-11-11", m), []))
           for m in ("TWSE", "TPEX")):
        h5_backup_info = _load_h5_v159_snapshot_backup(work_dir)
        if h5_backup_info is not None:
            for market in ("TWSE", "TPEX"):
                key = ("2026-11-11", market)
                if not any(x['verified_correction'] for x in candidates.get(key, [])):
                    group = h5_backup_info['records_by_market'][market]
                    candidates.setdefault(key, []).append({
                        'path': Path(h5_backup_info['csv_path']), 'records': group,
                        'correction': True, 'verified_correction': True,
                        'file_sha256': h5_backup_info['csv_sha256'],
                        'signature': _candidate_group_signature(group),
                        'trusted_basis': h5_backup_info['trusted_basis'],
                        'source_archive': h5_backup_info['zip_path'],
                    })
            log('[V159 H5 BACKUP PASS] ' + json.dumps({
                'zip_sha256': h5_backup_info['zip_sha256'],
                'source_v159_zip_sha256': h5_backup_info['source_v159_zip_sha256'],
                'source_v159_manifest_sha256': h5_backup_info['source_v159_manifest_sha256'],
                'canonical_sha256_by_market': h5_backup_info['canonical_sha256_by_market'],
                'h5_candidate_price_pairs': h5_backup_info['h5_candidate_price_pairs'],
                'h5_candidate_price_pair_downstream_ready': h5_backup_info['h5_candidate_price_pair_downstream_ready'],
            }, ensure_ascii=False))
        else:
            log('[V159 H5 BACKUP NOT FOUND] 固定SHA的2026-11-17 H5快照不存在；若原始v1.5.9修正CSV也缺失，將安全停止。')

    selected = {}
    selection_audit = []
    for key, meta in sorted(expected_map.items()):
        available = candidates.get(key, [])
        if not available:
            raise RuntimeError(
                f'v1.5.16日曆確認 {key[1]} {key[0]} 有行情，但找不到列數完全相符的既有標準增量；'
                f'預期 {meta["expected_rows"]} rows。'
            )
        if key == ('2026-11-11', 'TWSE'):
            trusted = [x for x in available if x['verified_correction']]
            if not trusted:
                raise RuntimeError('2026-11-11 TWSE 必須命中 SHA256 已封存的 v1.5.9 全日修正檔。')
            if len({x['signature'] for x in trusted}) != 1 or len({x['file_sha256'] for x in trusted}) != 1:
                raise RuntimeError('2026-11-11 TWSE 同SHA修正副本之間資料不一致。')
            chosen = max(trusted, key=lambda x: (x['path'].stat().st_mtime_ns, str(x['path'])))
        elif key == ('2026-11-11', 'TPEX'):
            trusted = [x for x in available if x['verified_correction']]
            if not trusted:
                raise RuntimeError('2026-11-11 TPEx 必須命中 SHA256 已封存的 v1.5.9 全日修正檔。')
            if len({x['signature'] for x in trusted}) != 1 or len({x['file_sha256'] for x in trusted}) != 1:
                raise RuntimeError('2026-11-11 TPEx 同SHA修正副本之間資料不一致。')
            chosen = max(trusted, key=lambda x: (x['path'].stat().st_mtime_ns, str(x['path'])))
        else:
            signatures = {x['signature'] for x in available}
            if len(signatures) > 1:
                correction_candidates = [x for x in available if x['correction']]
                if len(correction_candidates) != 1:
                    raise RuntimeError(
                        f'{key[1]} {key[0]}有多個全日來源且OHLCV不同，沒有唯一可信修正檔；'
                        + repr([str(x['path']) for x in available])
                    )
                chosen = correction_candidates[0]
            else:
                chosen = max(available, key=lambda x: (x['path'].stat().st_mtime_ns, str(x['path'])))
        _validate_adapter_day(chosen['records'], meta['expected_rows'], key[1], key[0], str(chosen['path']))
        selected[key] = chosen['records']
        selection_audit.append({
            'date': key[0], 'market': key[1], 'rows': len(chosen['records']),
            'source_file': str(chosen['path']), 'source_sha256': chosen['file_sha256'],
            'correction': chosen['correction'], 'verified_20261111_correction': chosen['verified_correction'],
            'trusted_basis': chosen.get('trusted_basis', 'EXACT_V1_5_9_CORRECTION_FILE_SHA256' if chosen['verified_correction'] else ''),
            'source_archive': chosen.get('source_archive', ''),
            'alternative_full_sources': len(available),
            'calendar_database_rows_before': meta.get('calendar_database_rows_before', meta['expected_rows']),
            'calendar_expected_rows': meta['expected_rows'],
            'calendar_expected_rows_basis': meta.get('expected_rows_basis', 'V1_5_15_DATABASE_ROWS_BEFORE'),
            'calendar_count_override': bool(meta.get('calendar_count_override', False)),
            'status': 'PASS',
        })

    records = []
    for key in sorted(selected):
        records.extend(selected[key])
    records.sort(key=lambda r: (r['date'], r['market'], r['code']))
    all_keys = [(r['date'], r['market'], r['code']) for r in records]
    if len(all_keys) != len(set(all_keys)):
        raise RuntimeError('跨來源合併後仍有重複自然鍵（market+date+code）。')

    # Per-market latest dates must match the v1.5.16 official calendar endpoint.
    latest = {}
    for r in records:
        latest[r['market']] = max(latest.get(r['market'], ''), r['date'])
    latest_expected = max(x['date'] for x in post_cutoff)
    if set(latest) != {'TWSE', 'TPEX'} or any(latest[m] != latest_expected for m in ('TWSE', 'TPEX')):
        raise RuntimeError(f'雙市場最後行情日期未一致：{latest}；官方日曆最後日={latest_expected}')

    adapter_dir = Path(work_dir) / 'v1_5x_official_increment_adapter'
    adapter_dir.mkdir(parents=True, exist_ok=False)
    delta_path = adapter_dir / '行情增量資料.csv.gz'
    headers = ['trade_date', 'market', 'instrument_code', 'instrument_name',
               'open', 'high', 'low', 'close', 'volume', 'price_change', 'source']
    with gzip.open(delta_path, 'wt', encoding='utf-8-sig', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=headers, extrasaction='ignore')
        writer.writeheader()
        for r in records:
            writer.writerow({
                'trade_date': r['date'], 'market': r['market'],
                'instrument_code': r['code'], 'instrument_name': r['name'],
                'open': '' if r['open'] is None else r['open'],
                'high': '' if r['high'] is None else r['high'],
                'low': '' if r['low'] is None else r['low'],
                'close': '' if r['close'] is None else r['close'],
                'volume': '' if r['volume'] is None else r['volume'],
                'price_change': '' if r['change'] is None else r['change'],
                'source': r['source'] or 'v1.5.16_calendar_verified_existing_official_increment',
            })
    if delta_path.stat().st_size <= 0:
        raise RuntimeError('轉接後 gzip 增量檔為空。')

    status_path = adapter_dir / '04_逐市場逐日補充狀態.csv'
    status_fields = ['date', 'market', 'status', 'rows', 'source', 'endpoint', 'raw_file', 'raw_sha256', 'note']
    with status_path.open('w', encoding='utf-8-sig', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=status_fields)
        writer.writeheader()
        for item in selection_audit:
            writer.writerow({
                'date': item['date'], 'market': item['market'], 'status': 'CACHE_VERIFIED_PASS',
                'rows': item['rows'], 'source': 'v1.5.x standardized increment; v1.5.16 calendar verified',
                'endpoint': '', 'raw_file': item['source_file'], 'raw_sha256': item['source_sha256'],
                'note': '自然鍵唯一、逐日列數與v1.5.16日曆及補抓證據一致；11/11採v1.5.9固定SHA全日替代。',
            })
    manifest_path = adapter_dir / '執行中繼資料.json'
    write_json(manifest_path, {
        'version': 'SSO_Market_Data_Continuation_TWSE_TPEX v1.5.16 adapter',
        'date_range_complete': True,
        'incremental_rows_total': len(records),
        'incremental_file_size_bytes': delta_path.stat().st_size,
        'last_date_by_market_after': latest,
        'incremental_data_path': str(delta_path),
        'source_v1_5_16_run_directory': str(run_folder),
        'source_v1_5_16_report': str(run_folder / V1516_REPORT_NAME),
        'status_file': str(status_path),
        'selected_market_day_groups': len(selection_audit),
        'selected_sources': selection_audit,
    })
    state_path = adapter_dir / '資料庫來源與更新狀態.json'
    base_stat = A_V417.stat()
    state = {
        'version': EXPECTED_MARKET_UPDATER_STATE_VERSION,
        'storage_mode': EXPECTED_MARKET_UPDATER_STORAGE_MODE,
        'persistent_database_path': str(delta_path),
        'original_source_database': str(A_V417),
        'original_source_sha256': EXPECTED_A_SHA256,
        'base_source_size_bytes': base_stat.st_size,
        'base_source_mtime_ns': base_stat.st_mtime_ns,
        'delta_size_bytes': delta_path.stat().st_size,
        'delta_rows': len(records),
        'headers': headers,
        'columns': {
            'date': 'trade_date', 'market': 'market', 'code': 'instrument_code',
            'name': 'instrument_name', 'open': 'open', 'high': 'high', 'low': 'low',
            'close': 'close', 'volume': 'volume', 'change': 'price_change', 'source': 'source',
        },
        'last_date_by_market': latest,
        'adapter': 'v1.5.16_READ_ONLY_OFFICIAL_INCREMENT_ADAPTER',
    }
    write_json(state_path, state)
    write_json(adapter_dir / '行情轉接稽核.json', {
        'version': 'SSO_main_v5.16_v1.5.16_adapter',
        'v1_5_16_run_directory': str(run_folder),
        'v1_5_16_report': report,
        'calendar_meta': calendar_meta,
        'historical_cutoff_exclusive': V1516_HISTORICAL_CUTOFF,
        'delta_rows': len(records), 'market_day_groups': len(selection_audit),
        'last_date_by_market': latest,
        'source_scan': scan_audit,
        'selected_sources': selection_audit,
        'v159_h5_backup': h5_backup_info,
        'drive_sources_modified': False,
        'model_only_input': True,
    })

    # Point the legacy validation functions at this temporary /content adapter.
    MARKET_STATE_DIR = adapter_dir
    DELTA_PATH = delta_path
    STATE_PATH = state_path
    log(f'[V1.5.16 ADAPTER PASS] run={run_folder.name}；market_days={len(selection_audit)}；rows={len(records):,}；latest={latest}')
    log('[V1.5.16 ADAPTER] Drive原始行情唯讀；僅在 /content 建立暫存gzip與狀態檔。')
    return {
        'directory': str(adapter_dir), 'delta_path': str(delta_path),
        'state_path': str(state_path), 'status_path': str(status_path),
        'manifest_path': str(manifest_path), 'source_run_directory': str(run_folder),
        'delta_rows': len(records), 'market_day_groups': len(selection_audit),
        'last_date_by_market': latest, 'selected_sources': selection_audit,
        'v159_h5_backup_used': bool(h5_backup_info),
        'v159_h5_backup_zip_sha256': h5_backup_info.get('zip_sha256') if h5_backup_info else None,
        'calendar_meta': calendar_meta,
    }


def test_v1516_adapter_contract():
    """Small deterministic tests for natural keys: date and market are part of identity."""
    def key(row): return (row['date'], row['market'], row['code'])
    rows = [
        {'date': '2026-11-16', 'market': 'TWSE', 'code': '2330'},
        {'date': '2026-11-17', 'market': 'TWSE', 'code': '2330'},
        {'date': '2026-11-17', 'market': 'TPEX', 'code': '2330'},
    ]
    if len({key(x) for x in rows}) != 3:
        raise AssertionError('跨日期／跨市場自然鍵識別失敗。')
    dup = rows + [dict(rows[1])]
    if len({key(x) for x in dup}) == len(dup):
        raise AssertionError('同市場同日同代號重複鍵未被識別。')

    calendar_sample = [
        {'date': '2026-11-11', 'market': 'TWSE', 'expected_rows': 1390},
        {'date': '2026-11-11', 'market': 'TPEX', 'expected_rows': 13752},
        {'date': '2026-11-12', 'market': 'TPEX', 'expected_rows': 1020},
    ]
    adjusted, audit = _apply_v159_pinned_calendar_row_counts(calendar_sample)
    adjusted_map = {(x['date'], x['market']): x for x in adjusted}
    if adjusted_map[('2026-11-11', 'TPEX')]['expected_rows'] != 1020:
        raise AssertionError('v1.5.9 TPEx 11/11 pinned row count was not applied.')
    if adjusted_map[('2026-11-11', 'TPEX')]['calendar_database_rows_before'] != 13752:
        raise AssertionError('Original v1.5.16 database row count was not retained for audit.')
    if adjusted_map[('2026-11-11', 'TPEX')]['calendar_count_override'] is not True:
        raise AssertionError('Inflated 11/11 TPEx calendar count override was not audited.')
    if adjusted_map[('2026-11-12', 'TPEX')]['expected_rows'] != 1020:
        raise AssertionError('Non-11/11 calendar row counts must remain unchanged.')
    if len(audit) != 2 or not all(x['basis'] == 'V1_5_9_ZIP_MANIFEST_FILE_SHA_AND_CANONICAL_SHA' for x in audit):
        raise AssertionError('Pinned v1.5.9 count audit is incomplete.')
    return {'cross_date_same_code': 'PASS', 'cross_market_same_code': 'PASS',
            'same_market_same_date_duplicate': 'PASS',
            'v159_pinned_1111_market_row_counts_override_calendar_anomaly': 'PASS',
            'non_1111_calendar_counts_preserved': 'PASS'}


def test_v1516_same_day_backfill_calendar_contract():
    """Synthetic network-free contract: a zero prior DB count is accepted only with a PASS API task and exact increment rows."""
    with tempfile.TemporaryDirectory(prefix='sso_v1516_calendar_contract_') as td:
        root = Path(td)
        cal = root / V1516_CALENDAR_NAME
        tasks = root / V1516_TASKS_NAME
        inc = root / '全市場標準化增量_20261118_20261118.csv'
        calendar_fields = ['trade_date', 'market', 'calendar_expected_open', 'calendar_evidence',
                           'database_rows_before', 'api_backfill_status']
        with cal.open('w', encoding='utf-8-sig', newline='') as f:
            w = csv.DictWriter(f, fieldnames=calendar_fields); w.writeheader()
            w.writerows([
                {'trade_date':'2026-11-18','market':'TWSE','calendar_expected_open':'True',
                 'calendar_evidence':'SYNTHETIC_OFFICIAL_OPEN','database_rows_before':0,'api_backfill_status':'PASS'},
                {'trade_date':'2026-11-18','market':'TPEX','calendar_expected_open':'True',
                 'calendar_evidence':'SYNTHETIC_OFFICIAL_OPEN','database_rows_before':0,'api_backfill_status':'PASS'},
            ])
        task_fields = ['trade_date','market','calendar_evidence','reason','api_status','rows',
                       'http_status','error','raw_file','response_sha256']
        with tasks.open('w', encoding='utf-8-sig', newline='') as f:
            w = csv.DictWriter(f, fieldnames=task_fields); w.writeheader()
            w.writerows([
                {'trade_date':'2026-11-18','market':'TWSE','api_status':'PASS','rows':2,'error':''},
                {'trade_date':'2026-11-18','market':'TPEX','api_status':'PASS','rows':1,'error':''},
            ])
        fields = ['trade_date','market','instrument_code','instrument_name','open','high','low','close',
                  'volume','price_change','source']
        with inc.open('w', encoding='utf-8-sig', newline='') as f:
            w = csv.DictWriter(f, fieldnames=fields); w.writeheader()
            w.writerows([
                {'trade_date':'2026-11-18','market':'TWSE','instrument_code':'1101','instrument_name':'A',
                 'open':10,'high':11,'low':9,'close':10,'volume':100,'price_change':0,'source':'UNIT_TEST'},
                {'trade_date':'2026-11-18','market':'TWSE','instrument_code':'1102','instrument_name':'B',
                 'open':10,'high':11,'low':9,'close':10,'volume':100,'price_change':0,'source':'UNIT_TEST'},
                {'trade_date':'2026-11-18','market':'TPEX','instrument_code':'3101','instrument_name':'C',
                 'open':10,'high':11,'low':9,'close':10,'volume':100,'price_change':0,'source':'UNIT_TEST'},
            ])
        report = {
            'version':'SSO_Market_Data_Continuation_TWSE_TPEX_v1.5.16',
            'check_window': {'start':'2026-11-18','end':'2026-11-18','calendar_days':30,
                             'execution_date_taipei':'2026-11-18','same_day_included':True,
                             'same_day_gate_hour_taipei':17},
            'expected_market_days':2, 'expected_session_dates':1,
            'backfill_rows':3, 'backfill_by_market':{'TWSE':2,'TPEX':1},
            'backfill_trade_dates':['2026-11-18'], 'increment_file':inc.name,
        }
        got, meta = _read_v1516_calendar(cal, root, report)
        got_map = {(x['date'],x['market']):x for x in got}
        assert got_map[('2026-11-18','TWSE')]['expected_rows'] == 2
        assert got_map[('2026-11-18','TPEX')]['expected_rows'] == 1
        assert all(x['expected_rows_basis'] == 'V1_5_16_VERIFIED_API_BACKFILL_AND_INCREMENT' for x in got)
        assert meta['backfill_evidence']['status'] == 'PASS'

        # A mismatch between task CSV and actual standardized increment must be blocked.
        with inc.open('a', encoding='utf-8', newline='') as f:
            w = csv.DictWriter(f, fieldnames=fields)
            w.writerow({'trade_date':'2026-11-18','market':'TWSE','instrument_code':'1103','instrument_name':'D',
                        'open':10,'high':11,'low':9,'close':10,'volume':100,'price_change':0,'source':'UNIT_TEST'})
        try:
            _read_v1516_calendar(cal, root, report)
        except RuntimeError:
            pass
        else:
            raise AssertionError('v1.5.16 task/increment row-count mismatch was not blocked')
    return {
        'zero_prior_count_requires_pass_task': 'PASS',
        'task_rows_match_increment_market_day_rows': 'PASS',
        'mismatched_increment_is_blocked': 'PASS',
    }


