# ============================================================================
# H5 candidate snapshot and audit-only GitHub upload
# ============================================================================

def collect_latest_h5_snapshot(work_dir: Path, run_start_ns: int, snapshot_folder_name: str | None = None) -> dict:
    roots = [PROJECT / '推薦結果' / '前瞻訊號快照', PROJECT / '推薦結果' / '非前瞻參考']
    hits = []
    pattern = 'SSO_v2.66_H5_*_v2.50_達標候選最多10檔.csv'
    for root in roots:
        if not root.is_dir():
            continue
        run_folder = root / snapshot_folder_name if snapshot_folder_name else None
        search = [run_folder] if run_folder is not None and run_folder.is_dir() else list(root.glob('SSO_main_v5_*'))
        for folder in search:
            for path in folder.glob(pattern):
                try:
                    if snapshot_folder_name or path.stat().st_mtime_ns >= run_start_ns:
                        hits.append(path)
                except OSError:
                    continue
    if not hits:
        raise FileNotFoundError(
            'v2.50流程已返回，但沒有找到本次執行產生的H5達標候選快照；'
            '不會自行用舊名單代替最新推薦。'
        )
    source = max(hits, key=lambda p: (p.stat().st_mtime_ns, str(p)))
    with source.open('r', encoding='utf-8-sig', newline='') as f:
        reader = csv.DictReader(f)
        fields = list(reader.fieldnames or [])
        rows = list(reader)
    required = {'股票代號', '公司名稱'}
    if not required.issubset(fields):
        raise RuntimeError(f'H5候選快照缺少必要欄位：{sorted(required - set(fields))}')
    if len(rows) > 10:
        raise RuntimeError(f'H5模型達標候選超過10檔：{len(rows)}；拒絕自行截斷。')
    codes = [norm_full_pool_code(r.get('股票代號')) for r in rows]
    if any(not c for c in codes) or len(codes) != len(set(codes)):
        raise RuntimeError('H5候選快照股票代號有空值或重複。')
    signal_match = re.search(r'_H5_(\d{4}-\d{2}-\d{2})_', source.name)
    signal_date = signal_match.group(1) if signal_match else ''
    if not signal_date:
        raise RuntimeError(f'無法從H5候選檔名辨識訊號日期：{source.name}')
    if rows:
        if '持有期間H' in fields and any(str(r.get('持有期間H', '')).strip() not in {'5', '5.0'} for r in rows):
            raise RuntimeError('候選快照中混入非H5資料。')
        if '訊號日期' in fields and any(parse_date(r.get('訊號日期')) != signal_date for r in rows):
            raise RuntimeError('H5候選快照的訊號日期與檔名不一致。')
    out_dir = Path(work_dir) / 'H5_10檔達標候選'
    out_dir.mkdir(parents=True, exist_ok=False)
    out_csv = out_dir / f'SSO_main_v5.16_H5_{signal_date}_達標候選最多10檔.csv'
    shutil.copy2(source, out_csv)
    summary = {
        'status': 'PASS' if rows else 'NO_QUALIFIED_CANDIDATES',
        'signal_date': signal_date,
        'horizon': 5,
        'candidate_count': len(rows),
        'max_candidates': 10,
        'padded_to_ten': False,
        'source_csv': str(source),
        'copied_csv': str(out_csv),
        'rows': rows,
        'fields': fields,
        'ranking_rule': '保留v2.50原模型合格候選排名；未放寬門檻、未補足10檔。',
        'forward_ledger_updated': False,
        'oos_claim': 'H5模型最新訊號快照；非已成熟的實際前瞻績效證明。',
    }
    write_json(out_dir / 'H5推薦快照摘要.json', summary)
    log(f'[H5 SNAPSHOT PASS] signal_date={signal_date}；qualified={len(rows)}/10；source={source}')
    if rows:
        show = ['合格候選排名', '股票代號', '公司名稱', '預測淨報酬', '估計淨獲利機率_校準', '上漲潛力', '候選狀態']
        show = [c for c in show if c in fields]
        log('[H5 TOP CANDIDATES] ' + ' | '.join(show))
        for row in rows:
            log('[H5 PICK] ' + ' | '.join(str(row.get(c, '') or '') for c in show))
    else:
        log('[H5 TOP CANDIDATES] 原模型本日沒有達標候選，不會降低門檻湊足10檔。')
    return summary


def _get_sso_github_token() -> str:
    token = os.environ.get('GITHUB_SSO_TOKEN', '').strip()
    if not token:
        try:
            from google.colab import userdata
            token = str(userdata.get('GITHUB_SSO_TOKEN') or '').strip()
        except Exception:
            token = ''
    if not token:
        raise RuntimeError('找不到Colab Secret GITHUB_SSO_TOKEN。')
    return token


def _sha256_file_local(path: Path) -> str:
    h = hashlib.sha256()
    with Path(path).open('rb') as f:
        for block in iter(lambda: f.read(8 * 1024 * 1024), b''):
            h.update(block)
    return h.hexdigest()


def _write_validated_audit_zip(bundle_dir: Path, zip_path: Path) -> Path:
    """Create and CRC-validate the recommendation audit ZIP with an explicit local dependency."""
    import zipfile
    bundle_dir = Path(bundle_dir)
    zip_path = Path(zip_path)
    with zipfile.ZipFile(zip_path, 'w', compression=zipfile.ZIP_DEFLATED, compresslevel=6) as zf:
        for path in sorted(bundle_dir.rglob('*')):
            if path.is_file():
                zf.write(path, path.relative_to(bundle_dir).as_posix())
    with zipfile.ZipFile(zip_path, 'r') as zf:
        bad = zf.testzip()
        if bad:
            raise RuntimeError(f'推薦稽核ZIP CRC失敗：{bad}')
    if zip_path.stat().st_size <= 0:
        raise RuntimeError('推薦稽核ZIP為空檔。')
    return zip_path


def test_recommendation_audit_zip_contract() -> dict:
    """Preflight the same ZIP creation/CRC path used at the end of the expensive model run."""
    import tempfile
    import zipfile
    with tempfile.TemporaryDirectory(prefix='sso_v516_audit_zip_test_') as td:
        root = Path(td)
        bundle = root / 'bundle'
        bundle.mkdir()
        (bundle / 'audit_probe.txt').write_text('SSO audit ZIP contract PASS', encoding='utf-8')
        target = root / 'probe.zip'
        _write_validated_audit_zip(bundle, target)
        with zipfile.ZipFile(target, 'r') as zf:
            if zf.namelist() != ['audit_probe.txt']:
                raise AssertionError(f'稽核ZIP成員清單異常：{zf.namelist()}')
            if zf.read('audit_probe.txt') != b'SSO audit ZIP contract PASS':
                raise AssertionError('稽核ZIP內容回讀不一致。')
    return {'audit_zip_creation': 'PASS', 'zip_crc': 'PASS', 'zip_readback': 'PASS'}


def create_recommendation_audit_bundle(work_dir: Path, recommendation: dict, run_id: str,
                                       bundle_name: str = 'GitHub_Audit_Bundle') -> Path:
    bundle = Path(work_dir) / bundle_name
    bundle.mkdir(parents=True, exist_ok=False)
    copy_candidates = [
        (Path(__file__) if '__file__' in globals() else None, 'SSO_main_v5_16.py'),
        (Path(work_dir) / 'SSO_main_v5_資料來源橋接與准入報告.json', 'SSO_main_v5_資料來源橋接與准入報告.json'),
        (Path(work_dir) / 'SSO_main_v5_缺值鍵值核對與橋接報告.json', 'SSO_main_v5_缺值鍵值核對與橋接報告.json'),
        (Path(recommendation['copied_csv']), Path(recommendation['copied_csv']).name),
        (Path(recommendation['copied_csv']).parent / 'H5推薦快照摘要.json', 'H5推薦快照摘要.json'),
        (Path(work_dir) / 'v1_5x_official_increment_adapter' / '行情轉接稽核.json', 'v1.5.16行情轉接稽核.json'),
    ]
    model_audits = sorted(Path('/content').glob('**/SSO_main_v5_v250_model_spec_audit.json'), key=lambda p: p.stat().st_mtime_ns)
    if model_audits:
        copy_candidates.append((model_audits[-1], 'v2.50模型規格稽核.json'))
    for source, name in copy_candidates:
        if source is not None and source.is_file():
            shutil.copy2(source, bundle / name)
    run_summary = {
        'version': 'SSO_main_v5.16', 'run_id': run_id,
        'recommendation': recommendation,
        'model': 'v2.50 unchanged; H5 only in this recommendation snapshot',
        'market_data_source': 'v1.5.16 official calendar and same-day backfill verified adapter',
        'drive_source_mutations': False,
        'github_main_modified': False,
    }
    # Avoid embedding the copied candidate rows twice in the audit JSON.
    run_summary['recommendation'] = {k: v for k, v in recommendation.items() if k not in {'rows', 'fields'}}
    write_json(bundle / 'SSO_main_v5_16_稽核摘要.json', run_summary)
    file_rows = []
    for path in sorted(bundle.rglob('*')):
        if path.is_file() and path.name != 'artifact_sha256_manifest.json':
            file_rows.append({'path': path.relative_to(bundle).as_posix(), 'bytes': path.stat().st_size,
                              'sha256': _sha256_file_local(path)})
    write_json(bundle / 'artifact_sha256_manifest.json', {'run_id': run_id, 'files': file_rows})
    zip_path = Path(work_dir) / f'SSO_main_v5_16_推薦稽核封存_{run_id}.zip'
    return _write_validated_audit_zip(bundle, zip_path)



def recover_v515_zip_nameerror_if_available() -> dict | None:
    """Recover the completed v5.15 H5 run when only its final ZIP step failed.

    This path is deliberately narrow: it requires the exact zipfile NameError,
    the original H5 copied CSV and its summary, plus the existing bridge/audit reports.
    It does not rerun the model or change the H5 candidate set.
    """
    content_root = Path('/content')
    reports = []
    for work_dir in content_root.glob('SSO_main_v5_15_*'):
        report_path = work_dir / 'SSO_main_v5_執行停止報告.json'
        if report_path.is_file():
            try:
                stop_report = read_json(report_path)
            except Exception:
                continue
            error = str(stop_report.get('error', ''))
            if error == "NameError: name 'zipfile' is not defined":
                reports.append((report_path.stat().st_mtime_ns, work_dir, stop_report))
    if not reports:
        return None
    _, work_dir, stop_report = max(reports, key=lambda x: x[0])
    source_run_id = work_dir.name[len('SSO_main_v5_15_'):]
    marker = work_dir / 'SSO_main_v5_16_推薦稽核補完報告.json'
    if marker.is_file():
        try:
            previous = read_json(marker)
            if previous.get('github_audit', {}).get('status') == 'PASS' and Path(previous.get('audit_zip', '')).is_file():
                log(f'[AUDIT RECOVERY SKIP] 原 v5.15 執行 {source_run_id} 已完成 ZIP 與 GitHub audit。')
                return {'status': 'ALREADY_RECOVERED', 'source_run_id': source_run_id,
                        'audit_zip': previous.get('audit_zip'), 'github_audit': previous.get('github_audit')}
        except Exception:
            pass

    recommendation = stop_report.get('h5_recommendation') or {}
    copied_csv = Path(str(recommendation.get('copied_csv', '')))
    summary_path = copied_csv.parent / 'H5推薦快照摘要.json' if str(copied_csv) else Path('/__missing__')
    required_reports = [work_dir / 'SSO_main_v5_資料來源橋接與准入報告.json',
                        work_dir / 'SSO_main_v5_缺值鍵值核對與橋接報告.json',
                        work_dir / 'v1_5x_official_increment_adapter' / '行情轉接稽核.json']
    missing = [str(p) for p in [copied_csv, summary_path, *required_reports] if not p.is_file()]
    if missing:
        raise RuntimeError('偵測到 v5.15 ZIP NameError，但補完所需檔案不完整；未重跑模型。缺少：' + repr(missing))

    saved_summary = read_json(summary_path)
    if Path(str(saved_summary.get('copied_csv', ''))).resolve() != copied_csv.resolve():
        raise RuntimeError('既有 H5 快照摘要的 copied_csv 指向不一致；拒絕補封存。')
    candidate_count = int(saved_summary.get('candidate_count', -1))
    if candidate_count < 0 or candidate_count > 10:
        raise RuntimeError(f'既有 H5 候選數無效：{candidate_count}')
    with copied_csv.open('r', encoding='utf-8-sig', newline='') as f:
        csv_rows = list(csv.DictReader(f))
    if len(csv_rows) != candidate_count:
        raise RuntimeError(f'既有 H5 CSV 列數與摘要不一致：{len(csv_rows)}/{candidate_count}')
    if str(saved_summary.get('signal_date', '')) != str(recommendation.get('signal_date', '')):
        raise RuntimeError('既有 H5 快照訊號日期與停止報告不一致。')

    # Use a distinct recovery folder; do not delete or overwrite the partially-built v5.15 bundle.
    recovery_id = f'{source_run_id}_RECOVER_{datetime.now(TAIPEI).strftime("%Y%m%d_%H%M%S")}_{uuid.uuid4().hex[:4]}'
    bundle_name = f'GitHub_Audit_Bundle_v5_16_RECOVERY_{recovery_id}'
    audit_zip = create_recommendation_audit_bundle(work_dir, saved_summary, recovery_id, bundle_name=bundle_name)
    try:
        github_result = github_audit_upload(audit_zip, work_dir / bundle_name, recovery_id)
    except Exception as exc:
        github_result = {'status': 'FAILED', 'error': f'{type(exc).__name__}: {exc}'}
        log('[GITHUB AUDIT WARNING] ' + github_result['error'])
    recovery_report = {
        'status': 'PASS' if github_result.get('status') == 'PASS' else 'AUDIT_ZIP_READY_GITHUB_WARNING',
        'recovered_from': "NameError: name 'zipfile' is not defined",
        'source_run_directory': str(work_dir), 'source_run_id': source_run_id,
        'signal_date': saved_summary.get('signal_date'),
        'candidate_count': candidate_count,
        'model_rerun': False,
        'audit_zip': str(audit_zip),
        'audit_zip_sha256': _sha256_file_local(audit_zip),
        'github_audit': github_result,
        'main_modified': False,
    }
    write_json(marker, recovery_report)
    log(f'[AUDIT RECOVERY PASS] signal_date={saved_summary.get("signal_date")}；qualified={candidate_count}/10；model_rerun=False')
    log(f'[AUDIT ZIP] {audit_zip}')
    if github_result.get('status') == 'PASS':
        log('[GITHUB AUDIT PASS] ' + github_result['url'])
    return recovery_report

def github_audit_upload(bundle_zip: Path, bundle_dir: Path, run_id: str) -> dict:
    token = _get_sso_github_token()
    git_work = Path(tempfile.mkdtemp(prefix='sso_v516_git_'))
    askpass = git_work / 'askpass.sh'
    askpass.write_text('#!/bin/sh\ncase "$1" in *Username*) echo x-access-token ;; *) echo "$SSO_GITHUB_TOKEN" ;; esac\n', encoding='utf-8')
    askpass.chmod(0o700)
    env = os.environ.copy()
    env.update({'GIT_ASKPASS': str(askpass), 'GIT_TERMINAL_PROMPT': '0', 'SSO_GITHUB_TOKEN': token})
    def git(*args, check=True):
        proc = subprocess.run(['git', *args], cwd=git_work, env=env, text=True,
                              stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if check and proc.returncode:
            raise RuntimeError(f'git {args[0]} {args[1] if len(args)>1 else ""}失敗：{proc.stderr[-1200:]}')
        return proc.stdout.strip(), proc.stderr.strip(), proc.returncode
    git('init')
    git('config', 'user.name', 'SSO Audit Bot')
    git('config', 'user.email', 'sso-audit@users.noreply.github.com')
    git('remote', 'add', 'origin', f'https://github.com/{REPO}.git')
    git('fetch', '--depth=1', 'origin', 'main')
    main_before, _, _ = git('rev-parse', 'FETCH_HEAD')
    if main_before != EXPECTED_MAIN_SHA:
        raise RuntimeError(f'GitHub main保護SHA不符：{main_before}；預期={EXPECTED_MAIN_SHA}；停止上傳。')
    branch = f'audit/sso-recommendation-v5-16-{run_id}'
    prefix = f'audit_readout/sso_recommendation_v5_16_{run_id}'
    git('checkout', '-b', branch, 'FETCH_HEAD')
    dest = git_work / prefix
    dest.mkdir(parents=True, exist_ok=True)
    shutil.copy2(bundle_zip, dest / bundle_zip.name)
    for src in bundle_dir.rglob('*'):
        if src.is_file():
            target = dest / src.relative_to(bundle_dir)
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, target)
    git('add', prefix)
    git('commit', '-m', f'SSO v5.16 H5 recommendation audit {run_id}')
    git('push', 'origin', f'HEAD:refs/heads/{branch}')
    commit_sha, _, _ = git('rev-parse', 'HEAD')
    git('fetch', '--depth=1', 'origin', f'refs/heads/{branch}:refs/remotes/origin/{branch}')
    branch_head, _, _ = git('rev-parse', f'refs/remotes/origin/{branch}')
    if branch_head != commit_sha:
        raise RuntimeError('GitHub audit branch head回讀不一致。')
    readback_count = 0
    for local in dest.rglob('*'):
        if not local.is_file():
            continue
        rel = f'{prefix}/{local.relative_to(dest).as_posix()}'
        raw = subprocess.run(['git', 'show', f'refs/remotes/origin/{branch}:{rel}'], cwd=git_work,
                             env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if raw.returncode != 0 or hashlib.sha256(raw.stdout).hexdigest() != _sha256_file_local(local):
            raise RuntimeError(f'GitHub audit逐檔SHA回讀不一致：{rel}')
        readback_count += 1
    remote_main = subprocess.run(['git', 'ls-remote', 'origin', 'refs/heads/main'], cwd=git_work,
                                 env=env, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True).stdout.split()
    main_after = remote_main[0] if remote_main else ''
    if main_after != main_before or main_after != EXPECTED_MAIN_SHA:
        raise RuntimeError(f'GitHub main前後SHA不一致：{main_before} -> {main_after}')
    return {'status': 'PASS', 'branch': branch, 'commit_sha': commit_sha,
            'branch_head_sha': branch_head, 'main_before': main_before,
            'main_after': main_after, 'main_unchanged': True,
            'file_readback_count': readback_count,
            'url': f'https://github.com/{REPO}/tree/{branch}/{prefix}'}


